{
	"name": "hevy-mcp",
	"version": "6.1.18",
	"private": false,
	"description": "A Model Context Protocol (MCP) server implementation that interfaces with the Hevy fitness tracking app and its API.",
	"repository": {
		"type": "git",
		"url": "https://github.com/chrisdoc/hevy-mcp"
	},
	"bin": {
		"hevy-mcp": "dist/cli.mjs"
	},
	"files": [
		"dist",
		"README.md",
		"server.json"
	],
	"type": "module",
	"main": "dist/index.mjs",
	"types": "dist/index.d.mts",
	"exports": {
		".": {
			"types": "./dist/index.d.mts",
			"import": "./dist/index.mjs"
		}
	},
	"publishConfig": {
		"access": "public"
	},
	"scripts": {
		"build": "tsdown -c tsdown.config.ts",
		"prepack": "node ../../scripts/server-manifest.mjs check && pnpm run build",
		"check:types": "tsc --noEmit -p tsconfig.json",
		"build:standalone": "cross-env HEVY_MCP_BUILD_MODE=standalone tsdown -c tsdown.config.ts"
	},
	"dependencies": {
		"@effect/opentelemetry": "4.0.0-rc.117",
		"@modelcontextprotocol/node": "^2.0.0",
		"@modelcontextprotocol/server": "^2.0.0",
		"@opentelemetry/api": "^1.9.1",
		"@opentelemetry/exporter-metrics-otlp-http": "^0.222.0",
		"@opentelemetry/exporter-trace-otlp-http": "^0.222.0",
		"@opentelemetry/resources": "^2.11.0",
		"@opentelemetry/sdk-metrics": "^2.11.0",
		"@opentelemetry/sdk-trace-base": "^2.11.0",
		"@opentelemetry/sdk-trace-node": "^2.11.0",
		"@sentry/node": "^10.75.0",
		"effect": "^4.0.0-rc.117",
		"semver": "^7.8.5",
		"zod": "^4.6.5"
	},
	"devDependencies": {
		"@hevy-mcp/core": "workspace:*",
		"@hevy-mcp/hevy-client": "workspace:*",
		"@sentry/core": "^10.75.0",
		"@types/node": "^26.6.2",
		"cross-env": "^10.1.0",
		"tsdown": "^0.23.0",
		"typescript": "^7.0.2"
	},
	"engines": {
		"node": ">=20.0.0"
	},
	"mcpName": "io.github.chrisdoc/hevy-mcp"
}

